const programmes=[
{id:'stem',name:'Little inventors lab',category:'STEM & ROBOTICS',age:'6-10',duration:60,icon:'⚙',img:'curiohub-maker-hero.jpg',desc:'Big questions. Hands-on experiments. Their first brilliant “aha!”',detail:'Build, test, and tinker with everyday materials. A playful introduction to scientific thinking, simple machines, and creative problem-solving.',learn:['Explore how things work through guided experiments','Build a mini project to share at home','Practise teamwork and learn from every attempt'],price:450},
{id:'art',name:'Messy hands, big ideas',category:'ART & MAKING',age:'3-6',duration:45,icon:'✿',img:'art.jpg',desc:'A splash of colour, a world of imagination. Let creativity run free.',detail:'A welcoming space to explore colour, texture, and shape. Children create with age-appropriate materials and make their own choices, with gentle guidance.',learn:['Experiment with colours and textures','Strengthen fine motor skills through making','Express ideas without a right or wrong answer'],price:350},
{id:'dance',name:'Move to your own beat',category:'MUSIC & MOVEMENT',age:'6-10',duration:60,icon:'♫',img:'dance.jpg',desc:'Find the rhythm. Feel the joy. Grow a little more confident.',detail:'Rhythm games, expressive movement, and playful choreography help children build confidence while discovering the joy of moving together.',learn:['Explore rhythm and coordination','Learn a short sequence with a small group','Grow confidence in self-expression'],price:400},
{id:'leaders',name:'Small voices, big impact',category:'LIFE SKILLS',age:'10-15',duration:75,icon:'✧',img:'learning.jpg',desc:'Stories, teamwork, and real-world skills for tomorrow’s changemakers.',detail:'A project-based club for young thinkers. Children explore communication, collaboration, and leadership through challenges grounded in everyday life.',learn:['Practise presenting ideas and listening to others','Collaborate on a community-minded mini project','Reflect on choices, confidence, and responsibility'],price:500},
{id:'play',name:'The wonder workshop',category:'PLAY & EXPLORATION',age:'3-6',duration:45,icon:'✦',img:'play.jpg',desc:'Stories, sensory discovery, and little adventures with new friends.',detail:'Supervised, time-bound exploration blends storytelling, sensory play, and open-ended challenges. Short sessions keep little explorers engaged.',learn:['Explore stories and imaginative play','Build social skills through shared activities','Discover materials, sounds, and movement'],price:300},
{id:'robotics',name:'Robotics & big ideas',category:'STEM & ROBOTICS',age:'10-15',duration:75,icon:'⚙',img:'curiohub-maker-hero.jpg',desc:'Make ideas move with design, logic, and hands-on challenges.',detail:'An introduction to robotics and design thinking through modular challenges. Learners plan, prototype, and improve a project together.',learn:['Explore mechanisms and simple logic','Prototype and troubleshoot a group project','Document ideas and share learning'],price:550}
];
let ageFilter='all',day=0,period='monthly';let basket=[],membership=null;try{basket=JSON.parse(localStorage.getItem('curiohub-basket')||'[]');membership=JSON.parse(localStorage.getItem('curiohub-plan')||'null');if(!Array.isArray(basket))basket=[]}catch{}const days=['Mon','Tue','Wed','Thu','Fri','Sat','Sun'];const money=n=>'₹'+n.toLocaleString('en-IN');const escapeHtml=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));function toast(s){document.querySelector('#toast').textContent=s;document.querySelector('#toast').classList.add('show');setTimeout(()=>document.querySelector('#toast').classList.remove('show'),3500)}function persist(){try{localStorage.setItem('curiohub-basket',JSON.stringify(basket));localStorage.setItem('curiohub-plan',JSON.stringify(membership))}catch{toast('Your browser could not save this selection.')}document.querySelector('#booking-count').textContent=basket.length?`(${basket.length})`:''}
function renderProgrammes(){const list=ageFilter==='all'?programmes:programmes.filter(p=>p.age===ageFilter);document.querySelector('#programme-grid').innerHTML=list.map(p=>`<article class="programme-card"><div class="card-img"><img src="assets/${p.img}" alt="${p.category.toLowerCase()} inspiration" loading="lazy"><span class="card-tag">${p.category}</span></div><div class="card-content"><div class="card-meta"><span>Ages ${p.age.replace('-', '–')}</span><span>${p.duration} min · In person</span></div><h3>${p.name}</h3><p>${p.desc}</p><button class="card-link" onclick="openProgramme('${p.id}')">Meet the programme <span>↗</span></button></div></article>`).join('')}
document.querySelector('#filters').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;ageFilter=b.dataset.filter;document.querySelectorAll('#filters button').forEach(x=>x.classList.toggle('active',x===b));renderProgrammes()});
const sessions=days.flatMap((d,i)=>[0,1,2].map((_,j)=>{const p=programmes[(i+j)%programmes.length];return{id:`${i}-${j}`,p:p.id,day:i,time:i>4?['10:00 AM','11:30 AM','3:00 PM'][j]:['4:00 PM','5:15 PM','6:30 PM'][j]}}));
function renderSchedule(){document.querySelector('#days').innerHTML=days.map((d,i)=>`<button class="${i===day?'active':''}" onclick="setDay(${i})" aria-pressed="${i===day}">${d}<small>${i>4?'Weekend':'After school'}</small></button>`).join('');const a=document.querySelector('#schedule-age').value;const filtered=sessions.filter(s=>s.day===day&&(a==='all'||programmes.find(p=>p.id===s.p).age===a));document.querySelector('#schedule-list').innerHTML=filtered.length?filtered.map(s=>{const p=programmes.find(p=>p.id===s.p);const added=basket.some(b=>b.id===s.id);return `<div class="session"><div class="session-time">${s.time}<small>${p.duration} minutes</small></div><div class="session-icon" aria-hidden="true">${p.icon}</div><div class="session-info"><h3>${p.name}</h3><p>Ages ${p.age.replace('-','–')} · School-partner pilot · Preview</p></div><div class="session-price">${money(p.price)}<small>Indicative / session</small></div><button class="btn outline" onclick="addSlot('${s.id}')">${added?'Added ✓':'Select slot ↗'}</button></div>`}).join(''):'<div class="empty">No preview sessions for this age group on this day.<p>Try another day or choose all ages.</p></div>'}
function setDay(d){day=d;renderSchedule()}document.querySelector('#schedule-age').addEventListener('change',renderSchedule);function addSlot(id){if(basket.some(b=>b.id===id)){openBookings();return}const s=sessions.find(s=>s.id===id);basket.push({...s,status:'Selected'});persist();renderSchedule();toast('Preview slot added to My adventures')}
const plans=[{name:'Spark',icon:'✧',price:1500,tag:'A little room to explore.',items:['4 sessions each month','Choose from age-fit programmes','Easy programme discovery']},{name:'Explorer',icon:'✳',price:2200,tag:'Make curiosity a weekly habit.',items:['8 sessions each month','Explore across programme categories','1 exploration session each month']},{name:'Trailblazer',icon:'↗',price:3000,tag:'More adventures. More possibilities.',items:['12 sessions each month','2 exploration sessions each month','1 discovery workshop each month']}];
function renderPlans(){
 const values=[
  'Discover a new interest with <strong>4 sessions each month</strong>, chosen from age-fit programmes.',
  'Build a weekly discovery habit with <strong>8 sessions across programme categories</strong> and an exploration session each month.',
  'Make more room for possibility with <strong>12 sessions, 2 exploration sessions</strong> and a discovery workshop each month.'
 ];
 document.querySelector('#plans').innerHTML=plans.map((p,i)=>{
  const rate=period==='quarterly'?p.price*.9:p.price;
  return `<article class="plan ${i===1?'featured':''}">
   <div class="pass-label">CurioHub membership <span aria-hidden="true">✳</span></div>
   <h3><span class="pass-icon" aria-hidden="true">${p.icon}</span>${p.name}</h3>
   <p class="plan-value">${values[i]}</p>
   <div class="plan-footer"><div class="plan-pricing"><span class="price-caption">${period==='quarterly'?'QUARTERLY PLAN':'MONTHLY PLAN'}</span><div class="plan-price">${money(rate)}<small> / month</small></div><div class="plan-sub">${period==='quarterly'?money(rate*3)+' billed quarterly':'Billed monthly'} · Indicative</div></div>
   <button class="btn" aria-label="Know more about ${p.name}" onclick="choosePlan(${i})">Know more <span aria-hidden="true">↗</span></button></div>
  </article>`
 }).join('');
}
document.querySelector('.billing').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;period=b.dataset.period;document.querySelectorAll('.billing button').forEach(x=>x.classList.toggle('active',x===b));renderPlans()});
function modal(html){document.querySelector('#modal-body').innerHTML=html;const d=document.querySelector('#modal');if(!d.open)d.showModal()}
function openProgramme(id){const p=programmes.find(p=>p.id===id);modal(`<h2>${p.name}</h2><p>${p.detail}</p><div class="detail-info"><span>Ages ${p.age.replace('-','–')}</span><span>${p.duration} minutes</span><span>In person</span></div><h3>What they’ll discover</h3><ul class="detail-list">${p.learn.map(x=>`<li>${x}</li>`).join('')}</ul><div class="preview-note">Proposed programme · Final curriculum and instructor details will be shared before the Hyderabad pilot launches.</div><button class="btn navy" onclick="viewProgrammeSchedule('${id}')">Find a preview session ↗</button>`)}function viewProgrammeSchedule(id){const s=sessions.find(s=>s.p===id);day=s.day;document.querySelector('#schedule-age').value=programmes.find(p=>p.id===id).age;renderSchedule();document.querySelector('#modal').close();location.hash='schedule'}
function choosePlan(i){const p=plans[i];const chosenPeriod=period;modal(`<h2>A little more ${p.name.toLowerCase()}.</h2><p>${p.tag} Choose this plan to save it alongside your adventures.</p><div class="detail-info"><span>${p.name}</span><span>${period==='monthly'?'Monthly':'Quarterly'}</span><span>${money(p.price*(period==='quarterly'?.9:1))} / month</span></div><ul class="detail-list">${p.items.map(x=>`<li>${x}</li>`).join('')}</ul><div class="preview-note">This is a preview selection, not an active membership. No payment is collected and no seats are reserved.</div><button id="save-plan" class="btn navy">Save membership preference ↗</button>`);document.querySelector('#save-plan').onclick=()=>{membership={name:p.name,period:chosenPeriod};persist();openBookings();toast('Membership preference saved on this device')}}
function openBookings(){modal(`<h2>Your little adventures.</h2><p>A home for the things you’d love to try.</p>${membership?`<div class="booking-item"><h3>${membership.name} membership</h3><p>${membership.period==='monthly'?'Monthly':'Quarterly'} · Preference saved</p><button onclick="membership=null;persist();openBookings()">Remove preference</button></div>`:''}${basket.length?basket.map(b=>{const p=programmes.find(p=>p.id===b.p);return `<div class="booking-item"><h3>${p.name}</h3><p>${days[b.day]} · ${b.time} · Ages ${p.age.replace('-','–')} · ${money(p.price)}</p><p>${b.status==='Requested'?'Preview request saved on this device':'Preview slot selected'}</p><button onclick="removeSlot('${b.id}')">Remove slot</button></div>`}).join(''):'<div class="empty">Your next adventure is waiting.<p>Browse the schedule and select a slot to get started.</p></div>'}${basket.length?`<div class="basket-total"><span>Indicative session total</span><strong>${money(basket.reduce((a,b)=>a+programmes.find(p=>p.id===b.p).price,0))}</strong></div><div class="preview-note">These are sample weekly slots. No live seats are reserved. Requests stay on this device and are not sent to CurioHub.</div><button class="btn navy" onclick="bookingForm()">Prepare a booking request ↗</button>`:'<button class="btn navy" onclick="document.querySelector(\'#modal\').close();location.hash=\'schedule\'" style="margin-top:20px">Explore the schedule ↗</button>'}`)}
function removeSlot(id){basket=basket.filter(b=>b.id!==id);persist();renderSchedule();openBookings()}
function bookingForm(){modal(`<h2>One step closer to wonder.</h2><p>Prepare your enquiry for ${basket.length} preview session${basket.length>1?'s':''}. Please use parent details only.</p><form id="booking-form"><label>Parent’s name<input name="parent" required maxlength="80" autocomplete="name" placeholder="Your name"></label><label>Email address<input name="email" type="email" required autocomplete="email" placeholder="you@example.com"></label><label>Child’s age group<select name="age" required><option value="">Select an age group</option><option>3–6 years</option><option>6–10 years</option><option>10–15 years</option></select></label><label class="checklabel"><input type="checkbox" required>I understand this is a preview enquiry saved only on this device, not a confirmed booking or a message sent to CurioHub.</label><button class="btn navy" type="submit">Save preview request ↗</button></form>`);document.querySelector('#booking-form').onsubmit=e=>{e.preventDefault();basket=basket.map(b=>({...b,status:'Requested'}));persist();renderSchedule();modal(`<div class="empty"><span style="font-size:45px">✦</span><h2 style="margin-top:20px">A little adventure, saved.</h2><p>Your preview request for ${basket.length} session${basket.length>1?'s':''} is saved on this device. Your name and email have not been stored or sent.</p></div><div class="preview-note">The Hyderabad pilot venue and dates are still to be announced. This request does not reserve a seat.</div><button class="btn navy" onclick="downloadRequest()">Download enquiry summary ↓</button>`)} }
function downloadRequest(){const lines=['CurioHub — Preview enquiry','Hyderabad school-partner pilot — venue and launch dates to be announced','No booking confirmed. No payment collected.','',...basket.map(b=>{const p=programmes.find(p=>p.id===b.p);return `${p.name} | ${days[b.day]} ${b.time} | Ages ${p.age} | ${money(p.price)} indicative`}),membership?`Membership preference: ${membership.name}, ${membership.period}`:'','Please confirm the final programme, venue, dates, availability, and pricing with CurioHub before enrolment.'];const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([lines.join('\n')],{type:'text/plain'}));a.download='CurioHub-preview-enquiry.txt';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function openInterest(topic){modal(`<h2>Let’s grow curious together.</h2><p>${escapeHtml(topic)} · Prepare your interest enquiry.</p><form id="interest-form"><label>Your name<input name="name" required maxlength="80" placeholder="Your name" autocomplete="name"></label><label>Email<input name="email" type="email" required placeholder="you@example.com" autocomplete="email"></label><label>Your interest<select name="interest"><option>Hyderabad pilot</option><option>School partnership</option><option>Community partnership</option><option>Future franchise interest</option></select></label><label>Anything you’d like us to know?<textarea name="note" rows="3" maxlength="600" placeholder="Your neighbourhood or organisation (optional)"></textarea></label><div class="preview-note">This preview prepares a downloadable enquiry. It does not subscribe you to updates or send your details to CurioHub.</div><button class="btn navy">Prepare my enquiry ↗</button></form>`);document.querySelector('#interest-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);const content=`CurioHub interest enquiry\nName: ${f.get('name')}\nEmail: ${f.get('email')}\nInterest: ${f.get('interest')}\nNote: ${f.get('note')}\n\nPrepared locally. Not submitted to CurioHub.`;const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([content],{type:'text/plain'}));a.download='CurioHub-interest-enquiry.txt';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);modal('<h2>Your enquiry is ready.</h2><p>Your enquiry has been downloaded so you can share it with the CurioHub team. It has not been submitted or stored on the site.</p><button class="btn navy" onclick="document.querySelector(\'#modal\').close()">Keep exploring →</button>')}}
function openFinder(){modal(`<h2>Follow their spark.</h2><p>Start with their age. There’s no perfect choice — just a lovely place to begin.</p><form id="finder"><label>Your child’s age group<select name="age"><option value="3-6">3–6 years · Explore & express</option><option value="6-10">6–10 years · Foundation & fun</option><option value="10-15">10–15 years · Independence & impact</option></select></label><button class="btn navy">Show their adventures ↗</button></form>`);document.querySelector('#finder').onsubmit=e=>{e.preventDefault();ageFilter=new FormData(e.target).get('age');document.querySelectorAll('#filters button').forEach(b=>b.classList.toggle('active',b.dataset.filter===ageFilter));renderProgrammes();document.querySelector('#modal').close();location.hash='programmes'}}
function openPrivacy(){modal('<h2>Small details. Thoughtful care.</h2><p>This preview stores selected sessions and a membership preference in your browser. Parent names, email addresses, and child age groups entered in the booking form are not stored or transmitted. Interest enquiries are downloaded to your device only.</p><p>External Google Fonts may receive standard browser connection information. All programme photos are illustrative. Final privacy, enrolment, safeguarding, and cancellation policies will be supplied before live bookings open.</p><button class="btn outline" onclick="basket=[];membership=null;persist();renderSchedule();document.querySelector(\'#modal\').close();toast(\'Saved selections cleared\')">Clear my saved selections</button>')}
document.querySelectorAll('nav a').forEach(a=>a.addEventListener('click',()=>document.querySelector('header').classList.remove('expanded')));document.querySelector('#modal').addEventListener('click',e=>{if(e.target===e.currentTarget){const r=e.currentTarget.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.currentTarget.close()}});renderProgrammes();renderSchedule();renderPlans();persist();
